import sys
from openpyxl import load_workbook


def is_num(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def to_num(v):
    if v is None:
        return None
    if is_num(v):
        return float(v)
    if isinstance(v, str):
        s = v.strip().replace(",", "").replace("$", "").replace(" ", "")
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            return None
    return None


AMT_KEYS = ("amount", "expense", "cost", "budget", "value", "actual",
            "spent", "planned", "total", "sum", "price", "due")
SKIP_KEYS = ("total", "grand", "sum", "combined")

path = sys.argv[1] if len(sys.argv) > 1 else "budget.xlsx"
try:
    wb = load_workbook(path, data_only=True)
except Exception as e:
    print(f"ERROR: could not open {path}: {e}")
    sys.exit(1)

grand = 0.0
for ws in wb.worksheets:
    rows = [r for r in ws.iter_rows(values_only=True)
            if any(v is not None for v in r)]
    print(f"--- Sheet: {ws.title!r} ({len(rows)} non-empty rows) ---")

    # Find an amount column from a header keyword in columns B..E.
    amt_col, start = None, 0
    for i, row in enumerate(rows):
        for j, cell in enumerate(row):
            if (isinstance(cell, str) and 1 <= j <= 4 and cell.strip()
                    and len(cell.strip()) <= 25
                    and any(k in cell.strip().lower() for k in AMT_KEYS)):
                amt_col, start = j, i + 1
                break
        if amt_col is not None:
            break

    # Fallback: first column that holds numbers.
    if amt_col is None:
        width = max((len(r) for r in rows), default=1)
        for j in range(min(5, width)):
            if any(to_num(r[j]) is not None for r in rows if j < len(r)):
                amt_col = j
                start = 0
                break

    sheet_total, n = 0.0, 0
    for i, row in enumerate(rows):
        if i < start or amt_col is None or amt_col >= len(row):
            print(f"  row {i+1}: {row}")
            continue
        label = row[0] if len(row) > 0 else None
        amt = row[amt_col]
        if isinstance(label, str) and any(k in label.strip().lower()
                                          for k in SKIP_KEYS):
            print(f"  row {i+1}: {row}   [skipped: rollup/total row]")
            continue
        v = to_num(amt)
        if v is not None:
            sheet_total += v
            n += 1
        print(f"  row {i+1}: {row}")
    print(f"  => subtotal: {sheet_total} from {n} rows (amount col idx {amt_col})")
    grand += sheet_total

print(f"TOTAL EXPENSES ACROSS ALL CATEGORIES: {grand}")

